let samples=[],prev=null;
self.onmessage=({data:d})=>{if(d.type==='reset'){samples=[];prev=null;self.postMessage({ok:true});return}if(d.type==='frame'){let g=new Uint8ClampedArray(d.buffer),n=g.length/4,gray=new Uint8Array(n),mean=0,clipping=0,sharp=0,motion=0;for(let i=0;i<n;i++){let v=Math.round(g[i*4]*.299+g[i*4+1]*.587+g[i*4+2]*.114);gray[i]=v;mean+=v;clipping+=v<5||v>250?1:0;if(prev)motion+=Math.abs(v-prev[i])}for(let i=65;i<n-65;i++)if(i%64!==0&&i%64!==63)sharp+=Math.abs(4*gray[i]-gray[i-1]-gray[i+1]-gray[i-64]-gray[i+64]);samples.push({time:d.time,motion:motion/n/255,sharpness:sharp/n/255,clipping:clipping/n,exposure:mean/n/255});prev=gray;self.postMessage({ok:true});return}if(d.type==='finish'){let ss=samples,mo=ss.map(s=>s.motion).sort((a,b)=>a-b),lum=ss.map(s=>s.exposure).sort((a,b)=>a-b),med=mo[Math.floor(mo.length/2)]||0,sm=Math.max(...ss.map(s=>s.sharpness),.001),mm=Math.max(...mo,.001),stats={luma:ss.reduce((n,s)=>n+s.exposure,0)/Math.max(1,ss.length),low:lum[Math.floor(lum.length*.1)]||0,high:lum[Math.floor(lum.length*.9)]||0,contrast:(lum[Math.floor(lum.length*.9)]||0)-(lum[Math.floor(lum.length*.1)]||0),clipping:ss.reduce((n,s)=>n+s.clipping,0)/Math.max(1,ss.length),motion:med},weight={'HIGH FASHION':.65,RAW:.2,CINEMATIC:.8,CLUB:-.4,DOCUMENTARY:.4}[d.intent]??.65,markers=[],chosen=[];let ranked=[...ss].sort((a,b)=>(b.sharpness/sm-weight*b.motion/mm-b.clipping*.4)-(a.sharpness/sm-weight*a.motion/mm-a.clipping*.4));for(let s of ranked){if(chosen.every(t=>Math.abs(s.time-t)>2)){chosen.push(s.time);markers.push({time:s.time,type:'best',label:'BEST MOMENT',detail:'鮮鋭度・動き・白黒の飽和率から候補化'})}if(chosen.length>=Math.min(12,Math.max(1,Math.ceil(d.duration/8))))break}let gap={CLUB:.6,'HIGH FASHION':1.5,DOCUMENTARY:4,CINEMATIC:2,RAW:3}[d.intent]||2,last=-10;for(let i=1;i<ss.length-1;i++){let s=ss[i];if(s.motion>Math.max(.012,med*1.5)&&s.motion>=ss[i-1].motion&&s.motion>ss[i+1].motion&&s.time-last>gap){markers.push({time:s.time,type:'motion',label:'MOTION ACCENT',detail:'画面内の動きのピーク。被写体の種類は未分類。'});last=s.time}}last=-10;for(let i=2;i<ss.length-2;i++){let s=ss[i];if(s.motion<Math.max(.005,med*.5)&&Math.max(ss[i-1].motion,ss[i-2].motion)>Math.max(.015,med*1.3)&&s.time-last>gap){markers.push({time:s.time,type:'still',label:'STILLNESS',detail:'動きの直後に静止する候補'});last=s.time}}let low=null,threshold=Math.max(.003,Math.min(.012,med*.4)),minimum={'HIGH FASHION':5,CLUB:1.5,RAW:7,DOCUMENTARY:8,CINEMATIC:4}[d.intent]||4;for(let s of [...ss,{time:d.duration,motion:1}]){if(s.motion<threshold&&low===null)low=s.time;else if(s.motion>=threshold&&low!==null){if(s.time-low>=minimum)markers.push({time:low,end:s.time,type:'quiet',label:'LOW VISUAL CHANGE',detail:(s.time-low).toFixed(1)+' sec — 意図的な間は残せます。'});low=null}}self.postMessage({markers:markers.sort((a,b)=>a.time-b.time).slice(0,250),samples:ss,stats,media:d.media,intent:d.intent,sampleFps:d.sampleFps,method:'低解像度フレームの鮮鋭度・輝度・差分解析。顔・視線・ポーズ認識は未実装。'});samples=[];prev=null}};
